import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, texture, mx_noise_float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, PointLight } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const toVec3 = (hex) => {
    const c = new Color(hex);
    return vec3(c.r, c.g, c.b);
  };

  const group = new Group();
  group.name = 'hub-collection-card-2-label';

  // ---- label plaque geometry ----
  const width = 1.6;
  const height = 0.46;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  const material = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.45,
    side: DoubleSide,
  });

  const uvNode = uv();

  // engineered vertical gradient: surface -> ink
  const gradientBase = mix(toVec3(colors.surface), toVec3(colors.ink), uvNode.y);

  // subtle grain
  const grainScalar = mx_noise_float(vec3(uvNode.mul(220.0), 0.0)).mul(0.035);
  const withGrain = gradientBase.add(vec3(grainScalar, grainScalar, grainScalar));

  // thin accent underline near bottom edge (<10% of frame)
  const bandLow = smoothstep(0.0, 0.012, uvNode.y);
  const bandHigh = smoothstep(0.04, 0.05, uvNode.y).oneMinus();
  const stripeMask = bandLow.mul(bandHigh);
  const accentColor = toVec3(colors.accent);

  const fallbackColorNode = mix(withGrain, accentColor, stripeMask.mul(0.9));
  material.colorNode = fallbackColorNode;

  const mesh = new Mesh(geometry, material);
  mesh.name = 'label-plate';
  group.add(mesh);

  // ---- brushed metal texture overlay ----
  let loadedTexture = null;
  const texPromise = config.imageUrl
    ? ctx.textureLoader
        .loadTexture(config.imageUrl)
        .then((tex) => {
          tex.colorSpace = THREE.SRGBColorSpace;
          loadedTexture = tex;
          const texNode = texture(tex, uvNode);
          const withMetal = mix(withGrain, texNode.rgb, 0.45);
          const finalColorNode = mix(withMetal, accentColor, stripeMask.mul(0.9));
          material.colorNode = finalColorNode;
          material.needsUpdate = true;
        })
        .catch(() => {})
    : Promise.resolve();

  // ---- rim/accent light for the machined-metal surface ----
  const rimLight = new PointLight(new Color(colors.accent), 0.8, 3.0, 2.0);
  rimLight.position.set(0.4, 0.2, 0.7);
  group.add(rimLight);

  // ---- headline text: "Collection 2" ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const headlineText = headlineItem?.text ?? 'Collection 2';
  const fontSizePx = headlineItem?.typography?.fontSize ?? 39;

  const textMesh = ctx.fontAtlas.createText(headlineText, {
    fontSize: fontSizePx,
    color: colors.paper,
    align: 'center',
    maxWidthPx: 420,
  });
  textMesh.name = 'label-headline';
  const TEXT_SCALE = 0.01;
  textMesh.scale.setScalar(TEXT_SCALE);
  textMesh.position.set(0, 0.02, 0.02);
  group.add(textMesh);

  // ---- scene placement ----
  const pos = config.scenePosition ?? { position: [0, 1, 0.06], rotation: [0, 0, 0], scale: [1, 1, 1] };
  // adapter applies scenePosition externally; do not re-apply.

  // ---- weighted-settle entrance motion ----
  group.scale.setScalar(0.97);
  const initialY = group.position.y;
  group.position.y = initialY + 0.05;

  const timeline = gsap.timeline();
  timeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timeline.to(
    group.position,
    {
      y: initialY,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timeline.kill();
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.position);

    group.remove(mesh);
    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }

    group.remove(rimLight);

    textMesh.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => {
          if (m.map) m.map.dispose();
          m.dispose();
        });
      }
    });
    group.remove(textMesh);
  };

  return group;
}
